26:   formatearFecha(date: string) {
27:     const [datePart, timePart, timeZone1, timeZone2] = date.split(' ');
28:     const [time, milliseconds] = timePart.split('.');
29: 
30:     // Combinar la fecha y la hora en el formato ISO
31:     const isoString = `${datePart}T${time}.${milliseconds}Z`;
32: 
33:     // Crear un objeto Date
34:     const dateObject = new Date(isoString);
35: 
36:     // Extraer las partes de la fecha
37:     const year = dateObject.getUTCFullYear();
38:     const month = String(dateObject.getUTCMonth() + 1).padStart(2, '0');
39:     const day = String(dateObject.getUTCDate()).padStart(2, '0');
40:     const hours = String(dateObject.getUTCHours()).padStart(2, '0');
41:     const minutes = String(dateObject.getUTCMinutes()).padStart(2, '0');
42:     const seconds = String(dateObject.getUTCSeconds()).padStart(2, '0');
43: 
44:     // Combinar todo en el formato deseado
45:     const formattedDate = `${year}/${month}/${day} ${hours}:${minutes}:${seconds}.${milliseconds} ${timeZone1} ${timeZone2}`;
46: 
47:     return formattedDate;
48:   }
